BEGIN;
CREATE TABLE IF NOT EXISTS vault_stepup_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES vault_workspaces(id),user_id uuid NOT NULL,method text NOT NULL,assurance_level integer NOT NULL CHECK(assurance_level BETWEEN 1 AND 3),expires_at timestamptz NOT NULL,consumed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS vault_export_grants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES vault_workspaces(id),object_id uuid NOT NULL REFERENCES vault_objects(id),requested_by uuid NOT NULL,destination_kind text NOT NULL CHECK(destination_kind IN('LINQA_MESSAGE','LINQA_GROUP','LINQA_SOCIAL_POST','SECURE_LINK','EMAIL')),destination_ref text,scope text NOT NULL DEFAULT 'COPY',state text NOT NULL DEFAULT 'PENDING' CHECK(state IN('PENDING','AUTHORIZED','EXECUTED','REVOKED','EXPIRED','DENIED')),expires_at timestamptz NOT NULL,stepup_session_id uuid REFERENCES vault_stepup_sessions(id),created_at timestamptz NOT NULL DEFAULT now(),executed_at timestamptz);
CREATE TABLE IF NOT EXISTS vault_audit_events(id bigserial PRIMARY KEY,workspace_id uuid NOT NULL,event_id uuid NOT NULL DEFAULT gen_random_uuid(),actor_user_id uuid,event_type text NOT NULL,subject_type text NOT NULL,subject_id text NOT NULL,request_id text,details jsonb NOT NULL DEFAULT '{}',prev_hash text,event_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,event_id));
COMMIT;
